406	    /** How a claim dated on a date rounds its figures: half up before the policy date (the sheet's today
407	     *  when it has none), half to even on or after it. */
408	    public RoundingMode rounding(LocalDate date) {
409	        LocalDate policy = policyDate == null ? today : policyDate;
410	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
411	    }
412	
413	    /** The late charge on an overdue claim's figure: for each full 30 days past the date its lateness runs
414	     *  from (its due-by plus any grace, see lateFrom) on the sheet's today, the late percent in force on that
415	     *  boundary date (that date plus 30, 60, 90 ... days) of the
416	     *  figure plus the charges of the boundaries before it (compounding), rounded to cents as its date
417	     *  rounds, the charges added up (a boundary at 0.00 adds nothing);
418	     *  0.00 for no figure (n/a). Only an OPEN or PENDING claim is overdue, so the caller asks only for those. */
419	    public BigDecimal lateCharge(BigDecimal figure, LocalDate lateFrom, LocalDate date) {
420	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
421	        if (figure == null) {
422	            return charge;
423	        }
424	        long boundaries = ChronoUnit.DAYS.between(lateFrom, today) / 30;
425	        RoundingMode rounding = rounding(date);
426	        for (long k = 1; k <= boundaries; k++) {
427	            charge = charge.add(figure.add(charge).multiply(latePctOn(lateFrom.plusDays(30 * k))).movePointLeft(2)
428	                    .setScale(2, rounding));
429	        }
430	        return charge;
431	    }
432	
433	    /** A live due of a claim dated on a date as it counts: at least the floor in force then; none (n/a)
434	     *  stays none. */
435	    public BigDecimal floored(BigDecimal due, LocalDate date) {
436	        return due == null ? null : due.max(floorOn(date));
437	    }
