439	    /** The fiscal year a date falls in, named by the calendar year its first day falls in. */
440	    public int fiscalYearOf(LocalDate date) {
441	        return date.getMonthValue() >= fiscalStartMonth ? date.getYear() : date.getYear() - 1;
442	    }
443	
444	    public int getLastSettleBatch() {
445	        return lastSettleBatch;
446	    }
447	
448	    /** Give out the sheet's next settle batch number. */
449	    public int nextSettleBatch() {
450	        return ++lastSettleBatch;
451	    }
452	}
